package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.NavigableMap;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.LateCharge;
import net.officefloor.hq.app.person.Person;

/**
 * A sheet's dated settings: for each key (floor, late-pct, terms, terms-&lt;grade&gt;, grace-&lt;grade&gt;, clerk-limit, clerk-limit-&lt;grade&gt;, cap, proof-threshold, proof-threshold-&lt;grade&gt;, note-threshold, review-threshold, rounding) the values
 * recorded, by from-date (a value null: blank). The value in force on a date is the one with the latest from-date on or
 * before it; before every from-date it is the sheet's starting value (floor 1.00, late percent 0.00, terms 14; none
 * for the clerk limit, the cap, the proof threshold, the note threshold, the review threshold, a grade's own terms, a grade's grace days, a grade's proof threshold and the rounding mode).
 */
public record DatedSettings(Map<String, NavigableMap<LocalDate, String>> values) {

    public static final String FLOOR = "floor";
    public static final String LATE_PCT = "late-pct";
    public static final String TERMS = "terms";
    public static final String CLERK_LIMIT = "clerk-limit";
    public static final String CAP = "cap";
    public static final String PROOF_THRESHOLD = "proof-threshold";
    public static final String NOTE_THRESHOLD = "note-threshold";
    public static final String REVIEW_THRESHOLD = "review-threshold";
    public static final String GRACE = "grace";
    public static final String ROUNDING = "rounding";

    /** The rounding modes that can be set, as typed. */
    public static final String HALF_UP = "half-up";
    public static final String HALF_EVEN = "half-even";

    /** The key of a grade's own terms. */
    public static String gradeTerms(String grade) {
        return TERMS + "-" + grade;
    }

    /** The audit field for a from-date typed with a save, " from=<date>", or "" when none was typed (the sheet's today). */
    public static String auditFrom(LocalDate from) {
        return from == null ? "" : " from=" + from;
    }

    /** The date a value saved with this from-date (null: none typed) is recorded from: it, else the sheet's today. */
    public static LocalDate fromOr(LocalDate from, LocalDate today) {
        return from == null ? today : from;
    }

    /** One value recorded from a date. */
    public record FromValue(LocalDate from, String value) {
    }

    /** The value of the key in force on the date (null: blank, or nothing recorded on or before it). */
    private String on(String key, LocalDate date) {
        NavigableMap<LocalDate, String> recorded = values.get(key);
        if (recorded == null || date == null) {
            return null;
        }
        Map.Entry<LocalDate, String> entry = recorded.floorEntry(date);
        return entry == null ? null : entry.getValue();
    }

    /** The floor in force on the date. */
    public BigDecimal floorOn(LocalDate date) {
        String value = on(FLOOR, date);
        return value == null ? SettingRepository.DEFAULT_FLOOR : new BigDecimal(value).setScale(2);
    }

    /** The late percent in force on the date. */
    public BigDecimal latePctOn(LocalDate date) {
        String value = on(LATE_PCT, date);
        return value == null ? SettingRepository.DEFAULT_LATE_PCT : new BigDecimal(value).setScale(2);
    }

    /** What an overdue claim is charged on the given today: the late percent in force on each 30-day boundary. */
    public LateCharge lateCharge(LocalDate today) {
        return new LateCharge(this::latePctOn, today);
    }

    /**
     * What an overdue claim of the person (null: none, no grace) is charged on the given today: the late percent in
     * force on each 30-day boundary, counted from its due-by plus the grace of the person's grade on its date.
     */
    public LateCharge lateCharge(LocalDate today, Person person) {
        return person == null ? lateCharge(today) : new LateCharge(this::latePctOn, (claim) -> graceFor(person, claim), today);
    }

    /** The key of a grade's grace days. */
    public static String gradeGrace(String grade) {
        return GRACE + "-" + grade;
    }

    /** The grade's grace days in force on the date (null: none). */
    public Integer graceOn(String grade, LocalDate date) {
        String value = grade == null ? null : on(gradeGrace(grade), date);
        return value == null ? null : Integer.valueOf(value);
    }

    /** The grace days for the person's claim: those of the person's grade in force on its date, in force then; else 0. */
    public int graceFor(Person person, Claim claim) {
        Integer grace = graceOn(person.gradeOn(claim.date()), claim.date());
        return grace == null ? 0 : grace;
    }

    /** The sheet's terms in days in force on the date. */
    public int termsOn(LocalDate date) {
        String value = on(TERMS, date);
        return value == null ? SettingRepository.DEFAULT_TERMS : Integer.parseInt(value);
    }

    /** The grade's own terms in force on the date (null: none, the sheet's terms). */
    public Integer gradeTermsOn(String grade, LocalDate date) {
        String value = on(gradeTerms(grade), date);
        return value == null ? null : Integer.valueOf(value);
    }

    /** The terms in days for a claim of the grade dated on the date: the grade's own in force then, else the sheet's. */
    public int termsFor(String grade, LocalDate date) {
        Integer own = grade == null ? null : gradeTermsOn(grade, date);
        return own != null ? own : termsOn(date);
    }

    /** The grades' own terms in force on the date, by grade (a grade with none left out). */
    public Map<String, Integer> gradeTermsOn(LocalDate date) {
        Map<String, Integer> terms = new LinkedHashMap<>();
        values.keySet().stream().filter((k) -> k.startsWith(TERMS + "-")).sorted().forEach((key) -> {
            String grade = key.substring(TERMS.length() + 1);
            Integer own = gradeTermsOn(grade, date);
            if (own != null) {
                terms.put(grade, own);
            }
        });
        return terms;
    }

    /** The clerk limit in force on the date (null: no limit). */
    public BigDecimal clerkLimitOn(LocalDate date) {
        String value = on(CLERK_LIMIT, date);
        return value == null ? null : new BigDecimal(value).setScale(2);
    }

    /** The key of a grade's own clerk limit. */
    public static String gradeClerkLimit(String grade) {
        return CLERK_LIMIT + "-" + grade;
    }

    /** The grade's own clerk limit in force on the date (null: none, the sheet's). */
    public BigDecimal gradeClerkLimitOn(String grade, LocalDate date) {
        String value = grade == null ? null : on(gradeClerkLimit(grade), date);
        return value == null ? null : new BigDecimal(value).setScale(2);
    }

    /** The clerk limit for a person of the grade on the date: the grade's own in force then, else the sheet's (null: no limit). */
    public BigDecimal clerkLimitFor(String grade, LocalDate date) {
        BigDecimal own = gradeClerkLimitOn(grade, date);
        return own != null ? own : clerkLimitOn(date);
    }

    /** The cap in force on the date (null: no cap). */
    public BigDecimal capOn(LocalDate date) {
        String value = on(CAP, date);
        return value == null ? null : new BigDecimal(value).setScale(2);
    }

    /** The proof threshold in force on the date (null: none). */
    public BigDecimal proofThresholdOn(LocalDate date) {
        String value = on(PROOF_THRESHOLD, date);
        return value == null ? null : new BigDecimal(value).setScale(2);
    }

    /** The key of a grade's own proof threshold. */
    public static String gradeProofThreshold(String grade) {
        return PROOF_THRESHOLD + "-" + grade;
    }

    /** The grade's own proof threshold in force on the date (null: none, the sheet's). */
    public BigDecimal gradeProofThresholdOn(String grade, LocalDate date) {
        String value = grade == null ? null : on(gradeProofThreshold(grade), date);
        return value == null ? null : new BigDecimal(value).setScale(2);
    }

    /** The proof threshold for a claim of the grade dated on the date: the grade's own in force then, else the sheet's (null: none). */
    public BigDecimal proofThresholdFor(String grade, LocalDate date) {
        BigDecimal own = gradeProofThresholdOn(grade, date);
        return own != null ? own : proofThresholdOn(date);
    }

    /**
     * Whether a claim of the date, of a person of the grade (null: none), with this due (null: n/a) needs a proof to be
     * settled or approved: its due is above the proof threshold for its grade in force on its date.
     */
    public boolean needsProof(String grade, LocalDate date, BigDecimal due) {
        BigDecimal threshold = proofThresholdFor(grade, date);
        return threshold != null && due != null && due.compareTo(threshold) > 0;
    }

    /** The note threshold in force on the date (null: none). */
    public BigDecimal noteThresholdOn(LocalDate date) {
        String value = on(NOTE_THRESHOLD, date);
        return value == null ? null : new BigDecimal(value).setScale(2);
    }

    /**
     * Whether a claim of the date with this due (null: n/a) needs a note to be opened: its due is above the note
     * threshold in force on its date.
     */
    public boolean needsNote(LocalDate date, BigDecimal due) {
        BigDecimal threshold = noteThresholdOn(date);
        return threshold != null && due != null && due.compareTo(threshold) > 0;
    }

    /** The review threshold in force on the date (null: none). */
    public BigDecimal reviewThresholdOn(LocalDate date) {
        String value = on(REVIEW_THRESHOLD, date);
        return value == null ? null : new BigDecimal(value).setScale(2);
    }

    /**
     * Whether a claim of the date with this due (null: n/a) goes to REVIEW when opened: its due is above the review
     * threshold in force on its date.
     */
    public boolean needsReview(LocalDate date, BigDecimal due) {
        BigDecimal threshold = reviewThresholdOn(date);
        return threshold != null && due != null && due.compareTo(threshold) > 0;
    }

    /** The rounding mode in force on the date, as typed (null: none). */
    public String roundingOn(LocalDate date) {
        return on(ROUNDING, date);
    }

    /** The rounding mode in force on the date (null: none, the policy date decides). */
    public RoundingMode roundingModeOn(LocalDate date) {
        String value = roundingOn(date);
        if (HALF_UP.equals(value)) {
            return RoundingMode.HALF_UP;
        }
        return HALF_EVEN.equals(value) ? RoundingMode.HALF_EVEN : null;
    }

    /** Every value recorded, by key, oldest from-date first. */
    public Map<String, List<FromValue>> history() {
        Map<String, List<FromValue>> history = new LinkedHashMap<>();
        values.forEach((key, recorded) -> history.put(key,
                recorded.entrySet().stream().map((e) -> new FromValue(e.getKey(), e.getValue())).toList()));
        return history;
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.sql.Date;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.NavigableMap;
import java.util.TreeMap;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.Rounding;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class SettingRepository {

    /** The floor a sheet starts with. */
    public static final BigDecimal DEFAULT_FLOOR = new BigDecimal("1.00");

    /** The terms a sheet starts with, in days. */
    public static final int DEFAULT_TERMS = 14;

    /** The late percent a sheet starts with. */
    public static final BigDecimal DEFAULT_LATE_PCT = new BigDecimal("0.00");

    /** The fiscal year start month a sheet starts with. */
    public static final int DEFAULT_FISCAL_START_MONTH = 1;

    private final JdbcTemplate jdbc;

    public SettingRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's settings: the dated ones in force on its today (and every value recorded), its policy date, its period numbering from date and its roles, by user name. */
    public Settings find(String sheetId) {
        List<UserRole> roles = jdbc.query("SELECT sheet_id, user_name, role FROM user_role WHERE sheet_id = ?"
                + " ORDER BY user_name", (rs, n) -> new UserRole(rs.getString("sheet_id"), rs.getString("user_name"),
                        Role.valueOf(rs.getString("role"))), sheetId);
        List<Date> found = jdbc.query("SELECT today FROM sheet WHERE id = ?", (rs, n) -> rs.getDate("today"), sheetId);
        LocalDate today = found.isEmpty() || found.get(0) == null ? LocalDate.now() : found.get(0).toLocalDate();
        DatedSettings dated = dated(sheetId);
        return new Settings(sheetId, dated.clerkLimitOn(today), dated.floorOn(today), dated.termsOn(today),
                dated.gradeTermsOn(today), dated.latePctOn(today), policyDate(sheetId), periodNumberingFrom(sheetId), entryDate(sheetId),
                dated.capOn(today), dated.proofThresholdOn(today), roles, dated, permissions(sheetId), graceDays(sheetId),
                today, delegations(sheetId), pot(sheetId), parent(sheetId), fiscalStartMonth(sheetId), alertThreshold(sheetId),
                escalateAfter(sheetId), reviewSla(sheetId), pendingSla(sheetId), proofKinds(sheetId), defaultGrade(sheetId),
                scoreMid(sheetId), scoreHigh(sheetId), scoreLog(sheetId), maxOpen(sheetId));
    }

    /** The sheet's dated settings: every value recorded, by key and from-date. */
    public DatedSettings dated(String sheetId) {
        Map<String, NavigableMap<LocalDate, String>> values = new LinkedHashMap<>();
        jdbc.query("SELECT setting_key, from_date, setting_value FROM setting_from WHERE sheet_id = ?"
                + " ORDER BY setting_key, from_date", (rs) -> {
                    values.computeIfAbsent(rs.getString("setting_key"), (k) -> new TreeMap<>())
                            .put(rs.getDate("from_date").toLocalDate(), rs.getString("setting_value"));
                }, sheetId);
        return new DatedSettings(values);
    }

    /** Record the key's value from the date (null: blank), replacing any value already recorded from that date. */
    public void saveDated(String sheetId, String key, LocalDate from, String value) {
        jdbc.update("DELETE FROM setting_from WHERE sheet_id = ? AND setting_key = ? AND from_date = ?",
                sheetId, key, Date.valueOf(from));
        jdbc.update("INSERT INTO setting_from (sheet_id, setting_key, from_date, setting_value) VALUES (?, ?, ?, ?)",
                sheetId, key, Date.valueOf(from), value);
    }

    /** The sheet's rounding policy date as set (null: blank, the sheet's today). */
    public LocalDate policyDate(String sheetId) {
        List<Date> date = jdbc.query("SELECT policy_date FROM sheet WHERE id = ?",
                (rs, n) -> rs.getDate("policy_date"), sheetId);
        return date.isEmpty() || date.get(0) == null ? null : date.get(0).toLocalDate();
    }

    /** How the sheet rounds the given claims' live figures on the given today: by the rounding mode in force on a claim's date, else by its policy date (blank: today). */
    public Rounding rounding(String sheetId, LocalDate today, List<Claim> claims) {
        LocalDate policyDate = policyDate(sheetId);
        return Rounding.of(policyDate == null ? today : policyDate, dated(sheetId)::roundingModeOn, claims);
    }

    /** Set the sheet's rounding policy date (null: blank, the sheet's today). */
    public void savePolicyDate(String sheetId, LocalDate policyDate) {
        jdbc.update("UPDATE sheet SET policy_date = ? WHERE id = ?", policyDate == null ? null : Date.valueOf(policyDate), sheetId);
    }

    /** The sheet's period numbering from date (null: blank, off). */
    public LocalDate periodNumberingFrom(String sheetId) {
        List<Date> date = jdbc.query("SELECT period_numbering_from FROM sheet WHERE id = ?",
                (rs, n) -> rs.getDate("period_numbering_from"), sheetId);
        return date.isEmpty() || date.get(0) == null ? null : date.get(0).toLocalDate();
    }

    /** Set the sheet's period numbering from date (null: blank, off). */
    public void savePeriodNumberingFrom(String sheetId, LocalDate from) {
        jdbc.update("UPDATE sheet SET period_numbering_from = ? WHERE id = ?", from == null ? null : Date.valueOf(from), sheetId);
    }

    /** The sheet's entry date (null: blank, off). */
    public LocalDate entryDate(String sheetId) {
        List<Date> date = jdbc.query("SELECT entry_date FROM sheet WHERE id = ?",
                (rs, n) -> rs.getDate("entry_date"), sheetId);
        return date.isEmpty() || date.get(0) == null ? null : date.get(0).toLocalDate();
    }

    /** Set the sheet's entry date (null: blank, off). */
    public void saveEntryDate(String sheetId, LocalDate entryDate) {
        jdbc.update("UPDATE sheet SET entry_date = ? WHERE id = ?", entryDate == null ? null : Date.valueOf(entryDate), sheetId);
    }

    /** The sheet's pot (null: blank, none). */
    public BigDecimal pot(String sheetId) {
        List<BigDecimal> pot = jdbc.query("SELECT pot FROM sheet WHERE id = ?", (rs, n) -> rs.getBigDecimal("pot"), sheetId);
        return pot.isEmpty() || pot.get(0) == null ? null : pot.get(0).setScale(2);
    }

    /** The sheet's alert threshold (null: blank, off). */
    public BigDecimal alertThreshold(String sheetId) {
        List<BigDecimal> threshold = jdbc.query("SELECT alert_threshold FROM sheet WHERE id = ?",
                (rs, n) -> rs.getBigDecimal("alert_threshold"), sheetId);
        return threshold.isEmpty() || threshold.get(0) == null ? null : threshold.get(0).setScale(2);
    }

    /** Set the sheet's alert threshold (null: blank, off). */
    public void saveAlertThreshold(String sheetId, BigDecimal threshold) {
        jdbc.update("UPDATE sheet SET alert_threshold = ? WHERE id = ?", threshold, sheetId);
    }

    /** Set the sheet's pot (null: blank, none), kept in its history under the sheet's today when it changes. */
    public void savePot(String sheetId, BigDecimal pot) {
        BigDecimal was = pot(sheetId);
        if (was == null ? pot == null : pot != null && was.compareTo(pot) == 0) {
            return;
        }
        jdbc.update("UPDATE sheet SET pot = ? WHERE id = ?", pot, sheetId);
        jdbc.update("INSERT INTO sheet_pot (sheet_id, on_date, pot) SELECT id, today, ? FROM sheet WHERE id = ?", pot,
                sheetId);
    }

    /** The sheet's pot as it stood on the date: the one set last on or before it (null: none). */
    public BigDecimal potOn(String sheetId, LocalDate on) {
        List<BigDecimal> pot = jdbc.query("SELECT pot FROM sheet_pot WHERE sheet_id = ? AND (on_date IS NULL OR on_date <= ?)"
                + " ORDER BY on_date DESC NULLS LAST, id DESC LIMIT 1", (rs, n) -> rs.getBigDecimal("pot"), sheetId,
                Date.valueOf(on));
        return pot.isEmpty() || pot.get(0) == null ? null : pot.get(0).setScale(2);
    }

    /** The sheet's parent sheet id (null: none). */
    public String parent(String sheetId) {
        List<String> parent = jdbc.query("SELECT parent_id FROM sheet WHERE id = ?", (rs, n) -> rs.getString("parent_id"), sheetId);
        return parent.isEmpty() ? null : parent.get(0);
    }

    /** The ids of the sheet's descendants (children, their children, ...), by id; none when it has none. */
    public List<String> descendants(String sheetId) {
        java.util.Set<String> found = new java.util.TreeSet<>();
        java.util.Deque<String> todo = new java.util.ArrayDeque<>(List.of(sheetId));
        while (!todo.isEmpty()) {
            for (String child : jdbc.query("SELECT id FROM sheet WHERE parent_id = ?", (rs, n) -> rs.getString("id"),
                    todo.pop())) {
                if (!child.equals(sheetId) && found.add(child)) {
                    todo.push(child);
                }
            }
        }
        return List.copyOf(found);
    }

    /** Set the sheet's parent sheet id (null: none). */
    public void saveParent(String sheetId, String parent) {
